    /// 🧩️ Projects owned semantic fields with typed relational refusals.
    pub fn project_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{
let count=self.spatial.len().checked_add(self.elements.len()).ok_or_else(|| ValueError::new(ValueRefusalKind::WorkLimit,"Semio model entity count overflow"))?;control.check_rows(count.checked_add(1).ok_or_else(|| ValueError::new(ValueRefusalKind::WorkLimit,"Semio model entity count overflow"))?)?;let mut entities=BTreeMap::new();let mut spatial_ids=BTreeMap::new();for(ordinal,node)in self.spatial.iter().enumerate(){let id=number(ordinal+1)?;if entities.insert(node.id.as_str(),id).is_some(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"duplicate Semio model native identity"));}spatial_ids.insert(node.id.as_str(),id);if ordinal%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;}}for(ordinal,element)in self.elements.iter().enumerate(){if entities.insert(element.id.as_str(),number(self.spatial.len()+ordinal+1)?).is_some(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"duplicate Semio model native identity"));}if ordinal%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;}}
