let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;p.insert_key_float("semio_model_document",1,&[Cell::Text(&self.schema)])?;
for(ordinal,node)in self.spatial.iter().enumerate(){let id=*entities.get(node.id.as_str()).ok_or_else(|| ValueError::new(ValueRefusalKind::InvariantViolated,"missing Semio spatial identity"))?;p.insert_key_float("semio_model_entity",id,&[Cell::Integer(1),Cell::Text("spatial"),Cell::Integer(number(ordinal)?),Cell::Text(&node.id)])?;p.insert_key_float("semio_model_spatial",id,&[Cell::Text(match node.kind{SpatialKind::Site=>"site",SpatialKind::Building=>"building",SpatialKind::Storey=>"storey",SpatialKind::Space=>"space"}),Cell::Text(&node.name),parents[&id].map(Cell::Integer).unwrap_or(Cell::Null)])?;placement(id,node.placement,&mut p)?;}
for(ordinal,element)in self.elements.iter().enumerate(){let id=*entities.get(element.id.as_str()).ok_or_else(|| ValueError::new(ValueRefusalKind::InvariantViolated,"missing Semio element identity"))?;let(class,name)=class(&element.class);p.insert_key_float("semio_model_entity",id,&[Cell::Integer(1),Cell::Text("element"),Cell::Integer(number(ordinal)?),Cell::Text(&element.id)])?;let spatial=match &element.spatial_id{None=>Cell::Null,Some(id)=>Cell::Integer(*spatial_ids.get(id.as_str()).ok_or_else(|| ValueError::new(ValueRefusalKind::InvalidValue,"dangling Semio model element spatial reference"))?)};p.insert_key_float("semio_model_element",id,&[Cell::Text(class),name.map(Cell::Text).unwrap_or(Cell::Null),spatial])?;placement(id,element.placement,&mut p)?;let(kind,target)=match &element.geometry{GeometryRef::None=>("none",Cell::Null),GeometryRef::Brep{brep_id}=>("brep",Cell::Text(brep_id)),GeometryRef::Mesh{mesh_id}=>("mesh",Cell::Text(mesh_id))};p.insert_key_float("semio_model_geometry_reference",id,&[Cell::Text(kind),target])?;
for(ordinal,pset)in element.psets.iter().enumerate(){let pset_id=p.insert_float("semio_model_property_set",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Text(&pset.name)])?;for(ordinal,property)in pset.properties.iter().enumerate(){let(kind,text,number_value,boolean)=match &property.value{PsetValue::Text{value}=>("text",Cell::Text(value),Cell::Null,Cell::Null),PsetValue::Number{value}=>("number",Cell::Null,Cell::Real(*value),Cell::Null),PsetValue::Boolean{value}=>("boolean",Cell::Null,Cell::Null,Cell::Integer(i64::from(*value)))};p.insert_float("semio_model_property",&[Cell::Integer(pset_id),Cell::Integer(number(ordinal)?),Cell::Text(&property.key),Cell::Text(kind),text,number_value,boolean])?;}}}
let mut ids=BTreeSet::new();for(ordinal,edge)in self.relations.iter().enumerate(){if !ids.insert(edge.id.as_str()){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"duplicate Semio model relation identity"));}let(kind,label)=relation(&edge.kind);p.insert_float("semio_model_relation",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&edge.id),Cell::Text(kind),label.map(Cell::Text).unwrap_or(Cell::Null),Cell::Integer(*entities.get(edge.from.as_str()).ok_or_else(|| ValueError::new(ValueRefusalKind::InvalidValue,"dangling Semio model relation source"))?),Cell::Integer(*entities.get(edge.to.as_str()).ok_or_else(|| ValueError::new(ValueRefusalKind::InvalidValue,"dangling Semio model relation target"))?)])?;}p.finish()
}

    /// 🧩️ Restores the owned typed subset inside its independently declared relational composition.
    pub fn reconstruct_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>, declared_schema: &str)->Result<Self,ValueError> {

control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(database,declared_schema,control.limits())?;let document=single_float_row(database,"semio_model_document")?;identity(document,2)?;if document.rowid!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio model document identifier"));}
let entities=rows(database,"semio_model_entity",5,control)?;let mut spatial_rows=rows(database,"semio_model_spatial",4,control)?;let mut element_rows=rows(database,"semio_model_element",4,control)?;let mut placements=rows(database,"semio_model_placement",11,control)?;let mut geometries=rows(database,"semio_model_geometry_reference",3,control)?;let mut names=BTreeMap::new();let mut native_ids=BTreeSet::new();let mut spatial_order=Vec::new();let mut element_order=Vec::new();for(&id,row)in &entities{if row.integer(1)?!=1||!native_ids.insert(row.text(4)?){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Semio model entity ownership or identity"));}names.insert(id,row.text(4)?);match row.text(2)?{"spatial"=>spatial_order.push(*row),"element"=>element_order.push(*row),_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unknown Semio model entity kind"))}}
