   let mut bytes=add(40,text(reader,control)?)?;let tag=byte(reader)?;bytes=add(bytes,relation(tag)?)?;if tag==5{bytes=add(bytes,text(reader,control)?)?;}text(reader,control)?;text(reader,control)?;census.row(bytes)
