 if value=="N"{return Ok(12)}let(tag,value)=value.split_at_checked(1).ok_or_else(invalid)?;if !matches!(tag,"B"|"M"){return Err(invalid())}let[id]=native::record(value,control)?;add(12,native::hex_text_extent(id,control)?)
